import { z } from 'zod/v3';
import {
  externalChange,
  invalidIntent,
  registerIntentTool,
  requiredText,
  type IntentResult,
  type IntentToolDependencies,
} from './intentTool';
import { okResult } from '../cli/envelope';

const TOOL_NAME = 'rivet_refresh_sources';
const SCOPE_MESSAGE =
  'Pass exactly one source scope: sourceId with family, or all: true with an optional family.';
const family = z.enum(['context', 'references']);
const familyCommand = {
  context: 'context',
  references: 'profile',
} as const;

const refreshedSources = (result: IntentResult): unknown[] => {
  const data = result.envelope.ok
    ? (result.envelope.data as { sources?: unknown[] })
    : {};
  return data.sources ?? [];
};

export const registerSourceSyncTools = (
  dependencies: IntentToolDependencies,
): void => {
  const { runCommand } = dependencies;
  registerIntentTool(
    dependencies,
    {
      name: TOOL_NAME,
      title: 'Refresh connected sources',
      description:
        'Start a refresh of already connected context documents and/or already imported reference collections. Pass sourceId with family for one source, or all: true for every connected source, optionally filtered by family. Returns per-source status (queued, skipped_off, skipped_in_progress, profile_disabled) after the work is queued, not after analysis finishes. A single source whose sync mode is off fails with source_sync_off; all: true reports it as skipped_off. Context refreshes keep the last good content on failure and preserve document IDs and receipts. Reference refreshes may add items and start analysis with the source’s last runtime, read only the approved collections, and never widen them. Does not bind a new context source, change a sync mode, connect an account, or approve a plan.',
      shape: {
        family: family.optional(),
        sourceId: requiredText.optional(),
        all: z.literal(true).optional(),
      },
      annotations: externalChange,
    },
    async (input) => {
      const hasSource = input.sourceId !== undefined;
      if (hasSource === (input.all === true))
        return invalidIntent(TOOL_NAME, SCOPE_MESSAGE);
      if (input.sourceId !== undefined) {
        if (!input.family) return invalidIntent(TOOL_NAME, SCOPE_MESSAGE);
        return runCommand(familyCommand[input.family], [
          'refresh',
          input.sourceId,
        ]);
      }
      if (input.family)
        return runCommand(familyCommand[input.family], ['refresh', '--all']);
      const context = await runCommand('context', ['refresh', '--all']);
      if (!context.envelope.ok) return context;
      const references = await runCommand('profile', ['refresh', '--all']);
      if (!references.envelope.ok) return references;
      return {
        envelope: okResult(TOOL_NAME, {
          sources: [
            ...refreshedSources(context),
            ...refreshedSources(references),
          ],
        }).envelope,
      };
    },
  );
};
